/** A tool on the connector's MCP server. The tool is pinned by its served definition; the manifest's verb, not the tool's annotations, is enforced. */
export type McpImplementationContract = {
  /** Rendered from the call input into the tool arguments. A multiplexed tool's discriminating argument is a literal here, never an input. */
  readonly arguments: unknown;
  /** How a write is confirmed: an independent call to a read tool, checked against what the write returned. Every write has one; a read has none. */
  readonly readback?: McpReadbackContract;
  readonly tool: string;
  /** sha256 over the served tool's name, description, input schema and annotations when the manifest was authored. A tool served with another definition is refused. */
  readonly tool_digest: string;
};

