/** An exact amount an operation moves, in the provider's smallest unit. */
export type OperationAmountContract = {
  readonly unit: string;
  readonly units: number;
};

/** A provider's charge for one call. Absent, no per-call charge is known and the call counts nothing against a money limit; `usd_micro: 0` is an explicit free. It is part of the operation digest: a price or basis change is a changed operation, confirmed again before it runs. */
export type OperationCostContract = {
  readonly per: CostBasisContract;
  /** Where the price was read. */
  readonly source: CostSourceContract;
  /** The page that states it, `https` only. */
  readonly source_url?: string;
  readonly usd_micro: number;
};

/** What a write produced: one reference, or one per element of a result array. The locator is rendered from the call's arguments, the instance's parameters and the call's result (`$result`); under `each` it reads the element as `$item`. A repeated write's result array is its items' outcomes: an effect is rendered for each applied item, whose `$item` is the provider's answer, and an item not applied produced nothing. Where the connector declares `references`, the kind is one of them and every locator matches its pattern. */
export type OperationEffectContract = {
  /** A `$result` pointer to the array the effect repeats over. */
  readonly each?: unknown;
  readonly kind: ExternalReferenceKindContract;
  readonly locator: unknown;
};

/** What the provider guarantees for this operation. Shared mechanics never assume more, and a use never tolerates more. */
export type OperationGuaranteesContract = {
  readonly provider_idempotency?: "enforced" | "inherent";
  readonly readback?: "unavailable";
};

/** What a hosted call does to a resource a purchase holds (S10, N11). runx Connect applies it at the provider's answer: a held value never reaches the kernel, which sees only the hold's evidence (its target, expiry and the value's digest). A hold is keyed by connector, credential and target, so a seller holds resources only in its own connector. */
export type OperationHoldContract = {
  readonly action: HoldActionContract;
  /** The `kind: purchase` credential held. */
  readonly credential: string;
  /** When the resource ends, one `$result` binding. A take and a refresh state it; a release does not. */
  readonly expires_at?: unknown;
  /** Each field of the credential and the one `$result` binding that fills it. Only a take fills fields. */
  readonly fields?: {
    readonly [key: string]: unknown;
  };
  /** The held resource. A take renders it from the call's public result; a refresh or release from the call's arguments, as the operations that use the credential render theirs. */
  readonly target: unknown;
};

/** An operation call before admission: everything a grant, a delegation or a person is asked to cover. Its digest is the one identity of the call: the execution term, the approval, the idempotency key and the receipt all bind it, so a call that changes in any of these fields is a new call. */
export type OperationIntentContract = {
  /** Digest of the act the call performs, when its caller states one. */
  readonly act_digest?: string;
  /** Present when the operation requires an amount. */
  readonly amount?: OperationAmountContract;
  /** Digest of the approval text a person is shown, when the call is gated. */
  readonly approval_digest?: string;
  readonly connector: string;
  readonly connector_digest: string;
  /** The instance fixes the placement, principal and account. */
  readonly instance_id: string;
  readonly manifest_digest: string;
  readonly operation: string;
  /** What the operation means: its verb, scopes, target and floors. */
  readonly operation_digest: string;
  readonly payload_digest: string;
  /** Digest of the caller's request key; present for mutations. */
  readonly request_key_digest?: string;
  readonly target: string;
};

/** The target an operation acts on, rendered from the call's arguments and the instance's parameters. The rendered value must equal the admitted target. */
export type OperationTargetContract = {
  /** A regular expression the rendered target must match whole, for a connector whose targets have a shape authority compares, such as a conversation locator. */
  readonly pattern?: string;
  readonly template: unknown;
};

/** The provider verbs an operation may declare. `read` makes the operation a read; every other verb makes it a mutation. */
export type OperationVerbContract = "read" | "write" | "comment" | "review" | "merge" | "create" | "update" | "delete" | "execute" | "revoke";

