/**
 * `runx history <run-id> --json`.
 *
 * Events come stream by stream, each stream in version order: a run and its child runs are streams of their own, and the store has no order across them. The cursor holds the last version returned for every stream of the run's tree, so a read after it never skips or repeats an event, including in child runs that started after the earlier read. `run` and `waiting` are read after the events, so they are never older than the last event returned.
 */
export type RunReadContract = {
  /** Opaque. Pass it as `--after` to read what follows. */
  readonly cursor: string;
  readonly events: readonly RunEventRecordContract[];
  /** Whether events past this page exist now. */
  readonly more: boolean;
  readonly run: RunReadSummaryContract;
  readonly schema: RunReadSchemaContract;
  /** Every request the run waits on, in full, so a host can rebuild a person's decision after a crash. */
  readonly waiting: readonly WaitedRequestContract[];
};

export type RunReadSchemaContract = "runx.run_read.v1";

